/**
 * Console font bundling guard.
 *
 * The web console names three faces in its token stacks (Manrope for `--sans`,
 * Space Grotesk for `--display`, which `--serif` aliases, and Roboto Mono for
 * `--mono`) and ships them inline as base64 woff2 data URIs in
 * `CONSOLE_FONT_FACE_CSS` (src/dashboard/design-fonts.ts), generated by
 * scripts/build-design-fonts.mjs from the committed files in assets/fonts/.
 *
 * A broken bundle fails silently: a truncated or undecodable face falls back to
 * the system stack, the page still renders, and the only symptom is "the
 * headings look different". These assertions catch that class in CI:
 *
 *   - the generated module is byte-identical to a fresh render from the
 *     committed woff2 files, whose sha256 values are pinned in the generator;
 *   - each face decodes to a woff2 (magic `wOF2`) above a byte floor;
 *   - each face's license sits beside it and its notice is in
 *     THIRD_PARTY_NOTICES.md, which ships in the npm package;
 *   - every page that interpolates the canonical tokens also carries the
 *     faces, and the one console page that serves a CSP admits data: fonts.
 */

import { describe, it, expect } from "vitest";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

import { CONSOLE_FONT_FACE_CSS } from "../../src/dashboard/design-fonts.js";
import { PAPER_INK_ROOT_TOKENS_CSS } from "../../src/dashboard/design-tokens.js";
import { renderDashboardV11Html } from "../../src/dashboard/v1_1/html.js";
import {
  MOBILE_COMPANION_CSP,
  renderMobileCompanionHTML,
} from "../../src/dashboard/mobile.js";
import {
  generateFleetSwitcherHTML,
  generateLoginHTML,
} from "../../src/principal-policy/dashboard-html.js";
import { renderPostureHomeHTML } from "../../src/principal-policy/posture-home-html.js";
import { renderPostureAgentHTML } from "../../src/principal-policy/posture-agent-html.js";
import { renderPostureEvidenceHTML } from "../../src/principal-policy/posture-evidence-html.js";
import { FACES, renderModule } from "../../scripts/build-design-fonts.mjs";

const SERVER_DIR = join(fileURLToPath(import.meta.url), "..", "..", "..");
const FONT_DIR = join(SERVER_DIR, "assets", "fonts");

/**
 * The smallest committed subset is 22,096 bytes (Space Grotesk). 16 KiB sits
 * well under every face and well over a header-only or half-written file, so a
 * truncated subset fails here instead of decoding to nothing in the browser.
 */
const MIN_FACE_BYTES = 16 * 1024;

/** The four bytes every woff2 file starts with (the format's signature). */
const WOFF2_MAGIC = "wOF2";

function parseFaces(css: string): Map<string, Buffer> {
  const out = new Map<string, Buffer>();
  const ruleRe = /@font-face\s*\{([^}]*)\}/g;
  let match: RegExpExecArray | null;
  while ((match = ruleRe.exec(css)) !== null) {
    const family = match[1].match(/font-family:\s*"([^"]+)"/)?.[1];
    const b64 = match[1].match(/url\("data:font\/woff2;base64,([A-Za-z0-9+/=]+)"\)/)?.[1];
    expect(family, "every @font-face names its family").toBeDefined();
    expect(b64, `${family} must be an inline woff2 data URI`).toBeDefined();
    out.set(family!, Buffer.from(b64!, "base64"));
  }
  return out;
}

const EMBEDDED = parseFaces(CONSOLE_FONT_FACE_CSS);
const FACE_LIST = FACES;

describe("console faces are bundled, complete, and licensed", () => {
  it("the generated module matches a fresh render from the committed woff2 files", () => {
    // renderModule() also re-checks each file's sha256 against the pin in the
    // generator, so a swapped font file fails here even if the module was
    // regenerated from it.
    const committed = readFileSync(join(SERVER_DIR, "src", "dashboard", "design-fonts.ts"), "utf8");
    expect(committed).toBe(renderModule());
  });

  it("embeds exactly the three faces the token stacks name", () => {
    expect([...EMBEDDED.keys()].sort()).toEqual(["Manrope", "Roboto Mono", "Space Grotesk"]);
    expect(FACE_LIST.map((f) => f.family).sort()).toEqual([...EMBEDDED.keys()].sort());
  });

  for (const face of FACE_LIST) {
    describe(face.family, () => {
      it("decodes to a woff2 above the byte floor, identical to the committed file", () => {
        const bytes = EMBEDDED.get(face.family)!;
        expect(bytes.subarray(0, WOFF2_MAGIC.length).toString("latin1")).toBe(WOFF2_MAGIC);
        expect(bytes.length).toBeGreaterThan(MIN_FACE_BYTES);
        expect(bytes.equals(readFileSync(join(FONT_DIR, face.file)))).toBe(true);
      });

      it("ships its license beside the font data and in the package notices", () => {
        const licensePath = join(FONT_DIR, face.license);
        expect(existsSync(licensePath)).toBe(true);
        expect(readFileSync(licensePath, "utf8")).toContain("SIL Open Font License, Version 1.1");
        const notices = readFileSync(join(SERVER_DIR, "THIRD_PARTY_NOTICES.md"), "utf8");
        expect(notices).toContain(face.family);
        expect(notices).toContain(face.subsetSha256);
      });
    });
  }

  it("every token stack names its bundled face first, with the system stack after it", () => {
    // The fallback is what keeps a page that omits the faces readable; the
    // first entry is what makes a page that carries them use them.
    expect(PAPER_INK_ROOT_TOKENS_CSS).toMatch(/--sans: "Manrope", -apple-system,/);
    expect(PAPER_INK_ROOT_TOKENS_CSS).toMatch(/--display: "Space Grotesk", "Manrope", -apple-system,/);
    expect(PAPER_INK_ROOT_TOKENS_CSS).toMatch(/--mono: "Roboto Mono", ui-monospace,/);
    expect(PAPER_INK_ROOT_TOKENS_CSS).toContain("--serif: var(--display);");
  });

  it("every page that interpolates the canonical tokens also carries the faces", () => {
    const pages: Record<string, string> = {
      "v1.1 dashboard": renderDashboardV11Html({ embedClient: false }),
      "mobile companion": renderMobileCompanionHTML(),
      "posture home": renderPostureHomeHTML(),
      "posture agent": renderPostureAgentHTML(),
      "posture evidence": renderPostureEvidenceHTML(),
      login: generateLoginHTML({ serverVersion: "9.9.9-test" }),
      "fleet switcher": generateFleetSwitcherHTML({
        serverVersion: "9.9.9-test",
        protocol: "http",
        currentHost: "127.0.0.1",
        currentPort: 1,
      }),
    };
    for (const [name, html] of Object.entries(pages)) {
      expect(html, `${name} carries the tokens`).toContain(PAPER_INK_ROOT_TOKENS_CSS);
      expect(html, `${name} carries the faces`).toContain(CONSOLE_FONT_FACE_CSS);
    }
  });

  it("the mobile companion CSP admits the inline faces and still no font origin", () => {
    // default-src 'self' alone blocks data: fonts, and the page would fall
    // back to the system stack with no error.
    expect(MOBILE_COMPANION_CSP).toContain("font-src 'self' data:;");
    expect(MOBILE_COMPANION_CSP).not.toMatch(/font-src[^;]*https?:/);
  });
});
